    47→// ExtractUserContent extracts user content from a raw message.
    48→// Handles both string and array content formats.
    49→// IDE-injected context tags (like <ide_opened_file>) are stripped from the result.
    50→// Returns empty string if the message cannot be parsed or contains no text.
    51→func ExtractUserContent(message json.RawMessage) string {
    52→	var msg UserMessage
    53→	if err := json.Unmarshal(message, &msg); err != nil {
    54→		return ""
    55→	}
    56→
    57→	// Handle string content
    58→	if str, ok := msg.Content.(string); ok {
    59→		return textutil.StripIDEContextTags(str)
    60→	}
    61→
    62→	// Handle array content (only if it contains text blocks)
    63→	if arr, ok := msg.Content.([]interface{}); ok {
    64→		var texts []string
    65→		for _, item := range arr {
    66→			if m, ok := item.(map[string]interface{}); ok {
    67→				if m["type"] == ContentTypeText {
    68→					if text, ok := m["text"].(string); ok {
    69→						texts = append(texts, text)
    70→					}
    71→				}
    72→			}
    73→		}
    74→		if len(texts) > 0 {
    75→			return textutil.StripIDEContextTags(strings.Join(texts, "\n\n"))
    76→		}
    77→	}
    78→
    79→	return ""
    80→}
