   251→// extractSessionData extracts session data from the shadow branch.
   252→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
   253→// agentType identifies the agent (e.g., "Gemini CLI", "Claude Code") to determine transcript format.
   254→func (s *ManualCommitStrategy) extractSessionData(repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType agent.AgentType) (*ExtractedSessionData, error) {
   255→	commit, err := repo.CommitObject(shadowRef)
   256→	if err != nil {
   257→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   258→	}
   259→
   260→	tree, err := commit.Tree()
   261→	if err != nil {
   262→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   263→	}
   264→
   265→	data := &ExtractedSessionData{}
   266→	// sessionID is already an "entire session ID" (with date prefix)
   267→	metadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   268→
   269→	// Extract transcript
   270→	var fullTranscript string
   271→	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
   272→		if content, contentErr := file.Contents(); contentErr == nil {
   273→			fullTranscript = content
   274→		}
   275→	} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
   276→		if content, contentErr := file.Contents(); contentErr == nil {
   277→			fullTranscript = content
   278→		}
   279→	}
   280→
   281→	// Process transcript based on agent type
   282→	if fullTranscript != "" {
   283→		// Check if this is a Gemini CLI transcript (JSON format, not JSONL)
   284→		isGeminiFormat := agentType == agent.AgentTypeGemini || isGeminiJSONTranscript(fullTranscript)
   285→
   286→		if isGeminiFormat {
   287→			// Gemini uses JSON format with a "messages" array
   288→			data.Transcript = []byte(fullTranscript)
   289→			data.FullTranscriptLines = 1 // JSON is a single "line"
   290→			data.Prompts = extractUserPromptsFromGeminiJSON(fullTranscript)
   291→			data.Context = generateContextFromPrompts(data.Prompts)
   292→		} else {
   293→			// Claude Code and others use JSONL format (one JSON object per line)
   294→			allLines := strings.Split(fullTranscript, "\n")
   295→
   296→			// Trim trailing empty lines (from final \n in JSONL)
   297→			for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   298→				allLines = allLines[:len(allLines)-1]
   299→			}
   300→
   301→			data.FullTranscriptLines = len(allLines)
   302→
   303→			// Always store the full transcript for complete session history
   304→			data.Transcript = []byte(strings.Join(allLines, "\n"))
   305→
   306→			// Extract prompts from the full transcript
   307→			data.Prompts = extractUserPromptsFromLines(allLines)
   308→
   309→			// Generate context from prompts
   310→			data.Context = generateContextFromPrompts(data.Prompts)
   311→		}
   312→	}
   313→
   314→	// Use tracked files from session state (not all files in tree)
   315→	data.FilesTouched = filesTouched
   316→
   317→	// Calculate token usage from the extracted transcript portion
   318→	if len(data.Transcript) > 0 {
   319→		transcriptLines, err := claudecode.ParseTranscript(data.Transcript)
   320→		if err == nil && len(transcriptLines) > 0 {
   321→			data.TokenUsage = claudecode.CalculateTokenUsage(transcriptLines)
   322→		}
   323→	}
   324→
   325→	return data, nil
   326→}
