   595→
   596→	// Simulate checkpoints coming in newest-first order from ListSessions
   597→	// but numbered with oldest=1, newest=N
   598→	checkpointDetails := []checkpointDetail{
   599→		{
   600→			Index:     3, // Newest checkpoint should have highest number
   601→			ShortID:   "ccc3333",
   602→			Timestamp: now,
   603→			Message:   "Third (newest) checkpoint",
   604→			Interactions: []interaction{{
   605→				Prompt:    "Latest change",
   606→				Responses: []string{},
   607→			}},
   608→		},
   609→		{
   610→			Index:     2,
   611→			ShortID:   "bbb2222",
   612→			Timestamp: now.Add(-time.Hour),
   613→			Message:   "Second checkpoint",
   614→			Interactions: []interaction{{
   615→				Prompt:    "Middle change",
   616→				Responses: []string{},
   617→			}},
   618→		},
   619→		{
   620→			Index:     1, // Oldest checkpoint should be #1
   621→			ShortID:   "aaa1111",
   622→			Timestamp: now.Add(-2 * time.Hour),
   623→			Message:   "First (oldest) checkpoint",
   624→			Interactions: []interaction{{
